import { Component, OnInit } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { G } from '../../../../../core/common/G';

@Component({
  selector: 'app-rules',
  templateUrl: './rules.component.html',
  styleUrls: ['./rules.component.scss']
})
export class RulesComponent implements OnInit {

  link = '';
  video: string | SafeUrl = 'brfwi7w';

  constructor(
    private sanitizer: DomSanitizer) { }

  ngOnInit(): void {

    this.link = G.TeacherRegisterLink;
    this.video = G.TeacherPanelVideo;
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.video +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.video;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}
